```json
{
  "root_causes": [
    {
      "service": "ts-preserve-service",
      "fault_kind": "http_aborted",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT attr_status_code, count(*) AS n, round(avg(duration)/1e6,2) AS avg_ms FROM abnormal_traces WHERE service_name='ts-preserve-service' AND attr_span_kind='Client' AND span_name='POST' GROUP BY attr_status_code ORDER BY n DESC",
          "claim": "About half of ts-preserve-service's outgoing POST calls end in Error after about 1.4 ms, with no child span, while the rest succeed."
        },
        {
          "kind": "trace",
          "sql": "SELECT k.service_name, k.span_name, count(*) AS n FROM normal_traces p JOIN normal_traces k ON k.parent_span_id=p.span_id WHERE p.service_name='ts-preserve-service' AND p.attr_span_kind='Client' AND p.span_name='POST' AND k.attr_span_kind='Server' GROUP BY ALL ORDER BY n DESC",
          "claim": "In normal traces, preserve's POSTs reach seat, order, travel, basic and food; in abnormal, only travel and basic receive them."
        },
        {
          "kind": "trace",
          "sql": "SELECT 'norm' AS period, count(*) AS food_post_server_spans FROM normal_traces WHERE service_name='ts-food-service' AND span_name='POST /api/v1/foodservice/orders' AND attr_span_kind='Server' UNION ALL SELECT 'abn', count(*) FROM abnormal_traces WHERE service_name='ts-food-service' AND span_name='POST /api/v1/foodservice/orders' AND attr_span_kind='Server'",
          "claim": "ts-food-service receives 38 POST /foodservice/orders in normal but zero in abnormal, while its GET path keeps serving traffic."
        },
        {
          "kind": "trace",
          "sql": "SELECT attr_status_code, attr_http_response_status_code, count(*) AS n FROM abnormal_traces WHERE service_name='ts-preserve-service' AND span_name='POST /api/v1/preserveservice/preserve' AND attr_span_kind='Server' GROUP BY ALL",
          "claim": "ts-preserve-service's own preserve endpoint returns HTTP 500 Error on 1498 requests in the abnormal period."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-preserve-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name AS callee, p.span_name, p.attr_status_code AS callee_status, c.service_name AS caller, c.attr_status_code AS caller_status, count(*) AS n, round(avg(c.duration)/1e6,1) AS caller_ms FROM abnormal_traces c JOIN abnormal_traces p ON p.parent_span_id=c.span_id WHERE c.service_name='ts-ui-dashboard' AND p.service_name='ts-preserve-service' AND p.span_name='POST /api/v1/preserveservice/preserve' GROUP BY ALL",
          "claim": "ts-ui-dashboard's calls to the preserve endpoint fail with Error whenever preserve returns Error, and take several seconds."
        }
      ]
    }
  ]
}
```

